CREATE TABLE IF NOT EXISTS student_directory (
  register_number TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  year TEXT NOT NULL,
  semester TEXT NOT NULL,
  batch TEXT NOT NULL,
  department TEXT NOT NULL,
  academic_year TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
ON CONFLICT (register_number) DO UPDATE SET name=EXCLUDED.name,year=EXCLUDED.year,semester=EXCLUDED.semester,batch=EXCLUDED.batch,department=EXCLUDED.department,academic_year=EXCLUDED.academic_year;